#include <vector>
#include <unordered_map>
#include <climits>
#include <algorithm>

using namespace std;

class Solution {
public:
    int countCoveredBuildings(int n, vector<vector<int>>& buildings) {
        unordered_map<int, int> minY, maxY, minX, maxX;
        for (const auto& b : buildings) {
            int x = b[0], y = b[1];
            if (!minY.count(x) || y < minY[x]) minY[x] = y;
            if (!maxY.count(x) || y > maxY[x]) maxY[x] = y;
            if (!minX.count(y) || x < minX[y]) minX[y] = x;
            if (!maxX.count(y) || x > maxX[y]) maxX[y] = x;
        }
        int ans = 0;
        for (const auto& b : buildings) {
            int x = b[0], y = b[1];
            if (minY[x] < y && y < maxY[x] && minX[y] < x && x < maxX[y]) ans++;
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int countCoveredBuildings(int n, int[][] buildings) {
        Map<Integer, Integer> minY = new HashMap<>(), maxY = new HashMap<>();
        Map<Integer, Integer> minX = new HashMap<>(), maxX = new HashMap<>();
        for (int[] b : buildings) {
            int x = b[0], y = b[1];
            minY.put(x, Math.min(minY.getOrDefault(x, Integer.MAX_VALUE), y));
            maxY.put(x, Math.max(maxY.getOrDefault(x, Integer.MIN_VALUE), y));
            minX.put(y, Math.min(minX.getOrDefault(y, Integer.MAX_VALUE), x));
            maxX.put(y, Math.max(maxX.getOrDefault(y, Integer.MIN_VALUE), x));
        }
        int ans = 0;
        for (int[] b : buildings) {
            int x = b[0], y = b[1];
            if (minY.get(x) < y && y < maxY.get(x) && minX.get(y) < x && x < maxX.get(y)) ans++;
        }
        return ans;
    }
}

